   203	        throw std::runtime_error("Could not read captured project metadata");
   204	
   205	    bool target_open = false;
   206	    auto rewritten = metadata;
   207	    rewritten += ".rewrite";
   208	    try {
   209	        const int entry_index = mz_zip_reader_locate_file(&source, entry, nullptr, 0);
   210	        if (entry_index < 0)
   211	            throw std::runtime_error("Captured project settings are missing");
   212	        size_t size = 0;
   213	        void* data = mz_zip_reader_extract_file_to_heap(&source, entry, &size, 0);
   214	        if (!data)
   215	            throw std::runtime_error("Could not read captured project settings");
   216	        std::string original(static_cast<const char*>(data), size);
   217	        mz_free(data);
