enum class LoadStrategy
{
    Default = 0,
    AddDefaultInstances = 1,
    CheckVersion = 2,
    LoadModel = 4,
    LoadConfig = 8,
    LoadAuxiliary = 16,
    Silence = 32,
    ImperialUnits = 64,
    AllowEmpty = 128,

    Restore = 0x10000 | LoadModel | LoadConfig | LoadAuxiliary | Silence,
};

